const DIGEST = /^[0-9a-f]{8}$/

/** One refusal of a snapshot line, carrying the 1-based line it was read from. */
export class SnapshotError extends Error {
  /**
   * @param {number} line - the 1-based line within the snapshot.
   * @param {string} message - the message the specification words, without the `error: <snapshot>: line N: ` prefix.
   */
  constructor(line, message) {
    super(message)
    this.name = 'SnapshotError'
    this.line = line
  }
}

/**
 * Parse a digest snapshot into the digest recorded for each path.
 * @param {string} text - the whole snapshot file.
 * @returns {Map<string, string>} the recorded digest by path.
 */
export function parseSnapshot(text) {
  const digests = new Map()
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  for (const [index, raw] of lines.entries()) {
